def is_valid_ipv4(s: str) -> bool:
    if not s or len(s.split('.')) != 4:
        return False
    parts = s.split('.')
    for part in parts:
        if not part.isdigit():
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
        if len(part) > 1 and part[0] == '0':
            return False
    return True
